(()=>{function sync(){const top=document.querySelector('.top');document.documentElement.style.setProperty('--app-header-height',(Math.max(0,top?.getBoundingClientRect().bottom||74))+'px')}window.addEventListener('DOMContentLoaded',()=>{sync();const top=document.querySelector('.top');if(top)new ResizeObserver(sync).observe(top)});window.addEventListener('resize',sync);window.addEventListener('scroll',sync,{passive:true,capture:true})})();
(()=>{const pinned=new Map();function pin(el,target){if(!el||!target||pinned.has(el))return;const marker=document.createComment('header-control-origin');el.before(marker);pinned.set(el,marker);target.append(el)}function arrange(){for(const [el,marker]of pinned){if(!marker.isConnected){el.remove();pinned.delete(el)}}document.querySelectorAll('.view.show>.panel').forEach(panel=>{const head=panel.querySelector(':scope>.head'),content=panel.querySelector(':scope>.content');if(!head||!content)return;let dock=head.querySelector(':scope>.fixed-header-tools');if(!dock){dock=document.createElement('div');dock.className='fixed-header-tools';head.append(dock)}const actions=head.querySelector('.shortcut-actions');if(actions){pin(content.querySelector('#jobs-add'),actions);pin(content.querySelector('.ti-group-form>button:first-child'),actions);pin(content.querySelector('.location-toolbar .location-add'),actions)}for(const selector of ['.jobs-toolbar','.financial-list-controls','.location-toolbar']){for(const el of content.querySelectorAll(selector))pin(el,dock)}dock.hidden=!dock.children.length})}window.addEventListener('DOMContentLoaded',()=>{let pending=false;new MutationObserver(()=>{if(pending)return;pending=true;queueMicrotask(()=>{pending=false;arrange()})}).observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['class']});arrange()})})();
